export const PHASES = [
  { n: 0, title: 'Phase 0 — specs and scaffold', goal: 'The spec set mirrors the PRD and is reviewed; the empty monorepo builds, tests, checks PRD coverage and runs CI.' },
  { n: 1, title: 'Phase 1 — R1 step 1: foundation, access, vehicles, SPK core', goal: 'Setup mode and Go live, sign-in, roles incl. Accounting, vendors, the Access Manager area and the Planner switch, audit log, file storage and compression, vehicles, classes and chassis layouts, the document master, and the SPK core with approvals, stamps and the scope lock (PRD §10 R1 step 1). Ends with UAT on staging (DEC-77).' },
  { n: 2, title: 'Phase 2 — R1 step 2: assignment engine, registry, SPK document (critical tier)', goal: "The engine runs each SPK's own steps, built in Create SPK and frozen at approval, with step time, verification in parallel, completion approval and the SPK document (PRD §10 R1 step 2). Engine first, on a dummy module (§8.3)." },
  { n: 3, title: 'Phase 3 — R1 step 3: Stock step, Part Purchase, parts inventory (high tier)', goal: 'Parts enter by Goods Receipt, leave by the Stock step, are bought outside by the Part Purchase step and are counted by stock opname, all through one stock ledger (PRD §10 R1 step 3).' },
  { n: 4, title: 'Phase 4 — R1 step 4: Mechanic Action, Part Check, Mobilisasi', goal: 'Repairs, troubleshooting and mobilisation run as registered modules with their masters; server and web here, phone screens in phase 7 (PRD §10 R1 step 4, DEC-99).' },
  { n: 5, title: 'Phase 5 — R1 step 5: tyres, Part Replacement and map, baseline, part age (high tier)', goal: 'Every tyre is traced from receipt to scrap and shown on the chassis map; part items carry their baseline, life used and early-failure alerts (PRD §10 R1 step 5).' },
  { n: 6, title: 'Phase 6 — R1 step 6: documents, PM, odometer, change requests, schedule, dashboards, notifications, requests, import', goal: 'The system runs day to day: documents renew, alerts draft SPKs, change requests amend SPKs, the schedule rolls forward, every role sees its work, and go-live data imports (PRD §10 R1 step 6).' },
  { n: 7, title: 'Phase 7 — R1 step 7: invoices, mobile app, push, go-live', goal: 'Completed SPKs are billed daily; Driver, Field Coordinator, Mechanic and System Admin work from the Android app with push; production goes live (PRD §10 R1 step 7, DEC-41, DEC-98). Starts after phases 1 to 6 pass.' },
];

